function compute(inputs) {
  const prior = inputs.prior;
  const sens = inputs.sensitivity;
  const fpr = inputs.fpr;
  const N = 1000;
  const pD = prior;
  const pNotD = 1 - prior;
  const pPos = sens * pD + fpr * pNotD;
  const posterior = (sens * pD) / pPos;
  const truePos = sens * pD * N;
  const falsePos = fpr * pNotD * N;
  const trueNeg = (1 - fpr) * pNotD * N;
  const falseNeg = (1 - sens) * pD * N;
  const table = {
    columns: ["Quantity", "Value"],
    rows: [
      ["P(D)", pD.toFixed(4)],
      ["P(+|D)", sens.toFixed(4)],
      ["P(+|¬D)", fpr.toFixed(4)],
      ["P(+)", pPos.toFixed(4)],
      ["P(D|+)", posterior.toFixed(4)],
      ["True positives", truePos.toFixed(1)],
      ["False positives", falsePos.toFixed(1)],
      ["True negatives", trueNeg.toFixed(1)],
      ["False negatives", falseNeg.toFixed(1)]
    ]
  };
  const insight = `With prevalence ${(prior*100).toFixed(1)}%, a positive test gives only ${(posterior*100).toFixed(1)}% chance of disease. ` +
    `The test is ${(sens*100).toFixed(1)}% sensitive but ${(fpr*100).toFixed(1)}% false positive. ` +
    `Out of ${N} people, ${truePos.toFixed(0)} true positives vs ${falsePos.toFixed(0)} false positives.`;
  return {
    posterior: posterior,
    pPos: pPos,
    truePos: truePos,
    falsePos: falsePos,
    trueNeg: trueNeg,
    falseNeg: falseNeg,
    table: table,
    insight: insight
  };
}
